// Compact Little-Endian Uint16 RLE byte array encoded in Base64
// Format: [val (1 byte), count_low (1 byte), count_high (1 byte)]
const RLE_BASE64 = "";

function decodeBase64ToBytes(b64: string): Uint8Array {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const lookup = new Uint8Array(256);
  for (let i = 0; i < chars.length; i++) {
    lookup[chars.charCodeAt(i)] = i;
  }
  let len = b64.length;
  if (b64.endsWith('==')) len -= 2;
  else if (b64.endsWith('=')) len -= 1;
  const bytes = new Uint8Array(Math.floor((len * 3) / 4));
  let p = 0;
  for (let i = 0; i < len; i += 4) {
    const b0 = lookup[b64.charCodeAt(i)];
    const b1 = lookup[b64.charCodeAt(i + 1)];
    const b2 = lookup[b64.charCodeAt(i + 2)];
    const b3 = lookup[b64.charCodeAt(i + 3)];
    bytes[p++] = (b0 << 2) | (b1 >> 4);
    if (p < bytes.length) bytes[p++] = ((b1 & 15) << 4) | (b2 >> 2);
    if (p < bytes.length) bytes[p++] = ((b2 & 3) << 6) | b3;
  }
  return bytes;
}

// Decompress grid into a flat Uint8Array (1200 * 900)
let cachedGrid: Uint8Array | null = null;

export function getRegionGrid(): Uint8Array {
  if (cachedGrid) return cachedGrid;

  const bytes = decodeBase64ToBytes(RLE_BASE64);
  const grid = new Uint8Array(REGION_GRID_WIDTH * REGION_GRID_HEIGHT);
  let writeOffset = 0;

  for (let i = 0; i < bytes.length; i += 3) {
    const val = bytes[i];
    const count = bytes[i + 1] | (bytes[i + 2] << 8);
    for (let c = 0; c < count; c++) {
      grid[writeOffset++] = val;
    }
  }

  cachedGrid = grid;
  return grid;
}

/**
 * Returns the month region (1..12) at the given Garden world coordinates,
 * or 0 if the coordinate is not plantable (water, road, landmark, stone, out of bounds).
 */
export function getRegionAtWorld(worldX: number, worldY: number): number {
  if (worldX < 0 || worldX >= GARDEN_WORLD_WIDTH || worldY < 0 || worldY >= GARDEN_WORLD_HEIGHT) {
    return 0;
  }

  const gx = Math.floor(worldX / REGION_GRID_SCALE);
  const gy = Math.floor(worldY / REGION_GRID_SCALE);

  if (gx < 0 || gx >= REGION_GRID_WIDTH || gy < 0 || gy >= REGION_GRID_HEIGHT) {
    return 0;
  }

  const grid = getRegionGrid();
  return grid[gy * REGION_GRID_WIDTH + gx];
}

/**
 * Returns true if the coordinate is on approved plantable grass.
 */
export function isPlantableGrass(worldX: number, worldY: number): boolean {
  return getRegionAtWorld(worldX, worldY) > 0;
}
